const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsa = ee.Geometry.Point([139.4936, -20.7256]).buffer(20000); // 20km buffer
  const townsville = ee.Geometry.Point([146.8169, -19.2590]).buffer(20000); // 20km buffer
  const startDate = '2019-01-27';
  const endDate = '2019-02-10';

  // 2. Data Acquisition
  const precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const collectionSize = precipCol.size().getInfo();
  if (collectionSize === 0) {
    print("No precipitation data found for the period.");
    print("<answer>C1</answer>");
    return;
  }

  // Sum precipitation over the period
  const totalPrecip = precipCol.sum();

  // 3. Processing - Get rainfall for both regions
  const mountIsaRainfall = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const townsvilleRainfall = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // Get pixel counts to check for valid data
  const mountIsaCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  const townsvilleCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation');

  // 4. Get values and validate
  const mountIsaVal = mountIsaRainfall.getInfo();
  const townsvilleVal = townsvilleRainfall.getInfo();
  const mountIsaPixels = mountIsaCount.getInfo();
  const townsvillePixels = townsvilleCount.getInfo();

  print(`Collection size: ${collectionSize} images`);
  print(`Mount Isa - Rainfall: ${mountIsaVal?.toFixed(1)} mm, Valid pixels: ${mountIsaPixels}`);
  print(`Townsville - Rainfall: ${townsvilleVal?.toFixed(1)} mm, Valid pixels: ${townsvillePixels}`);

  // 5. Validation & Final Answer
  if (mountIsaPixels === 0 || townsvillePixels === 0) {
    print("No valid pixels in one or both regions.");
    print("<answer>C2</answer>");
    return;
  }

  if (mountIsaVal === null || townsvilleVal === null || 
      isNaN(mountIsaVal) || isNaN(townsvilleVal) ||
      mountIsaVal < 0 || townsvilleVal < 0) {
    print("Invalid precipitation values calculated.");
    print("<answer>C3</answer>");
    return;
  }

  // Convert mm to cm and check threshold (45 cm = 450 mm)
  const threshold = 450; // mm
  const mountIsaMeets = mountIsaVal >= threshold;
  const townsvilleMeets = townsvilleVal >= threshold;

  print(`Mount Isa meets 45cm threshold: ${mountIsaMeets}`);
  print(`Townsville meets 45cm threshold: ${townsvilleMeets}`);

  if (mountIsaMeets && townsvilleMeets) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
